INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000850161','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000850161","revision":1,"targetId":"80000000-0000-4000-8000-000000008516","prompt":"Der Akku des Akkuschraubers war leer; mit einem ___ konnte er weiterarbeiten.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"An additional charged battery restores power.","de":"Ein weiterer geladener Akku liefert Strom."},"options":[{"id":"0","text":"Ersatzmotor"},{"id":"1","text":"Ersatzschlüssel"},{"id":"2","text":"Ersatzakku"},{"id":"3","text":"Ersatzreifen"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"2"}],"explanation":{"en":"Ersatzakku means spare battery. An additional charged battery restores power.","de":"Ersatzakku bedeutet zusätzlicher austauschbarer Akku. Ein weiterer geladener Akku liefert Strom."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Der Akku des Akkuschraubers war leer; mit einem Ersatzakku konnte er weiterarbeiten.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L689 (bf2957fa80ee28b7ff3251b581f3bb9587bbafbb56121f85813f93d6e20d4b5c), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
