INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000850170','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000850170","revision":1,"targetId":"80000000-0000-4000-8000-000000008517","prompt":"Während der Autoreparatur stellte die Werkstatt ein ___ bereit.","instruction":{"en":"Choose the noun that best completes the German sentence.","de":"Wähle das Nomen, das den deutschen Satz am besten ergänzt."},"hint":{"en":"A temporary vehicle replaces the car being repaired.","de":"Ein anderes Fahrzeug wird während der Reparatur genutzt."},"slots":[{"id":"noun","label":"Nomen","options":[{"id":"0","text":"Ersatzfahrzeug"},{"id":"1","text":"Ersatzteil"},{"id":"2","text":"Fahrradschloss"},{"id":"3","text":"Parkticket"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"0"}]}],"explanation":{"en":"Ersatzfahrzeug means replacement vehicle. A temporary vehicle replaces the car being repaired.","de":"Ersatzfahrzeug bedeutet Fahrzeug zur vorübergehenden Nutzung anstelle eines anderen. Ein anderes Fahrzeug wird während der Reparatur genutzt."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Während der Autoreparatur stellte die Werkstatt ein Ersatzfahrzeug bereit.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/nouns.jsonl:L690 (976eedae369c8377a6e2918f230f3e7b580cdfcd7a1ae8b88a08f966283b52b5), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
