INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000860020','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000860020","revision":1,"targetId":"80000000-0000-4000-8000-000000008602","prompt":"Wir haben eine Stunde Zeit, um uns in der Altstadt ___ und die Gebäude anzuschauen.","instruction":{"en":"Choose the verb or verb form that best completes the German sentence.","de":"Wähle das Verb oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"They want to explore the area visually.","de":"Sie möchten sich die Umgebung ansehen."},"slots":[{"id":"verb","label":"Verb oder Verbform","options":[{"id":"0","text":"umzusehen"},{"id":"1","text":"umzuhören"},{"id":"2","text":"umzuziehen"},{"id":"3","text":"umzumelden"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"verb","optionId":"0"}]}],"explanation":{"en":"sich umsehen means look around or search visually. They want to explore the area visually.","de":"sich umsehen bedeutet sich etwas ansehen oder nach etwas suchen. Sie möchten sich die Umgebung ansehen."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Wir haben eine Stunde Zeit, um uns in der Altstadt umzusehen und die Gebäude anzuschauen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L728 (1beb32fed0e4f2a883c821c1d1053688082cddc60de2d41b15de5463e2dad33d), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
