INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000860021','1','choice','{"type":"choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000860021","revision":1,"targetId":"80000000-0000-4000-8000-000000008602","prompt":"Im Möbelhaus hat sie sich nach einem neuen Tisch ___.","instruction":{"en":"Choose the verb or verb form that best completes the German sentence.","de":"Wähle das Verb oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"She looked through the furniture selection.","de":"Sie sah sich das Angebot an Möbeln an."},"options":[{"id":"0","text":"umgehört"},{"id":"1","text":"umgesehen"},{"id":"2","text":"umgezogen"},{"id":"3","text":"umgemeldet"}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"choice","optionId":"1"}],"explanation":{"en":"sich umsehen means look around or search visually. She looked through the furniture selection.","de":"sich umsehen bedeutet sich etwas ansehen oder nach etwas suchen. Sie sah sich das Angebot an Möbeln an."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Im Möbelhaus hat sie sich nach einem neuen Tisch umgesehen.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L728 (1beb32fed0e4f2a883c821c1d1053688082cddc60de2d41b15de5463e2dad33d), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
