INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000000860030','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000000860030","revision":1,"targetId":"80000000-0000-4000-8000-000000008603","prompt":"Im Vertrag hat er sich zur Verschwiegenheit ___.","instruction":{"en":"Choose the verb or verb form that best completes the German sentence.","de":"Wähle das Verb oder die Verbform, die den deutschen Satz am besten ergänzt."},"hint":{"en":"The agreement imposes a binding duty.","de":"Der Vertrag legt eine verbindliche Pflicht fest."},"slots":[{"id":"verb","label":"Verb oder Verbform","options":[{"id":"0","text":"entschuldigt"},{"id":"1","text":"vorbereitet"},{"id":"2","text":"beworben"},{"id":"3","text":"verpflichtet"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"verb","optionId":"3"}]}],"explanation":{"en":"sich verpflichten zu means make a binding commitment. The agreement imposes a binding duty.","de":"sich verpflichten zu bedeutet sich verbindlich zu etwas verpflichten. Der Vertrag legt eine verbindliche Pflicht fest."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"Im Vertrag hat er sich zur Verschwiegenheit verpflichtet.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises based on lexical/grammar facts from pinned apps/web/data/pos/verbs.jsonl:L729 (a839a1f4fb1f388283dcbedfe4a1932a185ba68604bb8d9b846a5e9b6ac77c7a), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
